import{_ as t,o,c as d,a2 as s}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Notes and Claude","description":"","frontmatter":{},"headers":[],"relativePath":"guides/notes-and-claude.md","filePath":"guides/notes-and-claude.md"}'),a={name:"guides/notes-and-claude.md"};function n(i,e,r,l,c,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="notes-and-claude" tabindex="-1">Notes and Claude <a class="header-anchor" href="#notes-and-claude" aria-label="Permalink to &quot;Notes and Claude&quot;">​</a></h1><p>Every Keel game keeps its notes in <code>Docs/</code>, an Obsidian vault, with one layout shared by all games. The layout, a few hooks and a set of skills let Claude Code pick up the project in a new chat by reading a few small notes instead of the whole vault, and keep those notes true as the code changes.</p><h2 id="the-vault-layout" tabindex="-1">The vault layout <a class="header-anchor" href="#the-vault-layout" aria-label="Permalink to &quot;The vault layout&quot;">​</a></h2><p>A new game gets the skeleton from <code>Starter/Docs/</code> (empty tables and headings, copied once by <code>keel.js new</code>; the game owns them from then on).</p><table tabindex="0"><thead><tr><th>Where</th><th>What goes in it</th><th>Source of truth?</th></tr></thead><tbody><tr><td><code>Docs/Start Here.md</code></td><td>The hub: every note linked with a one-line description. Claude reads it first</td><td>—</td></tr><tr><td><code>Docs/Status.md</code></td><td>Where the build is: <strong>Current</strong>, <strong>Last</strong> and <strong>Next</strong>, one or two lines each</td><td>—</td></tr><tr><td><code>Docs/Done.md</code></td><td>Every finished piece of work, newest last. Status&#39;s Last is always its last row</td><td>—</td></tr><tr><td><code>Docs/Look Later.md</code></td><td>Side notes, open decisions, before-launch tasks. Claude opens it only when pointed there</td><td>—</td></tr><tr><td><code>Docs/Systems/</code></td><td>How the code is built: one note per system, <code>Game Already Exists</code> (the game&#39;s reusable code) and <code>Game Tooling</code> (its own hooks). Keel&#39;s notes are in <code>Systems/Keel/</code>, read-only. A system with several notes gets its own subfolder</td><td><strong>Yes</strong>, for code</td></tr><tr><td><code>Docs/Design/</code></td><td>Settled game design. <code>Design Index</code> (table of contents), <code>Design Status</code>, <code>System Spec Template</code></td><td><strong>Yes</strong>, for design</td></tr><tr><td><code>Docs/Brainstorm/</code></td><td>Ideas, research, drafts, rejected options. <code>Brainstorm Status</code> lists them</td><td><strong>No</strong></td></tr><tr><td><code>Docs/Completed Build Orders/</code></td><td>Finished build plans, ignored by Git</td><td><strong>No</strong></td></tr></tbody></table><p>During feature work Claude reads only <code>Systems/</code> and <code>Design/</code>; <code>Brainstorm/</code> is opened only when you point to a note.</p><h2 id="how-notes-stay-current" tabindex="-1">How notes stay current <a class="header-anchor" href="#how-notes-stay-current" aria-label="Permalink to &quot;How notes stay current&quot;">​</a></h2><ul><li><strong><code>code:</code> lists.</strong> Every <code>Systems/</code> note lists the files it documents in its frontmatter (a path ending in <code>/</code> covers a folder).</li><li><strong><code>note-lookup</code></strong> (after each edit) tells Claude which notes list the edited file, so it opens only those.</li><li><strong><code>docs-check</code></strong> (when Claude ends a turn) flags uncommitted <code>src/</code> files whose notes are older than the code, or that no note lists. Claude updates the notes, or says the step is still in progress. It reports the same findings only once.</li><li><strong>Notes stay small.</strong> A note that grows past about 10 KB is split by part into <code>Systems/&lt;System&gt;/</code> with a small hub note, so an edit points at a small note.</li><li><strong>Notes describe the present.</strong> They are edited in place; history lives in Git.</li></ul><h2 id="the-working-loop" tabindex="-1">The working loop <a class="header-anchor" href="#the-working-loop" aria-label="Permalink to &quot;The working loop&quot;">​</a></h2><ol><li><strong><code>/next-system</code></strong> prints <code>Status.md</code> and, when Next names a build order step (&quot;[[Combat Build Order]] step 4&quot;), only that step&#39;s plan. Claude reports where things stand and offers to start.</li><li><strong>Build the step</strong>, checked against its <strong>Check</strong>.</li><li><strong>The step close</strong> (the <code>vault-notes</code> skill): update the step&#39;s notes, record the check, add the row to <code>Done.md</code>, rewrite <code>Status.md</code>, shrink the step to one line in the build order. Done when <code>docs-check</code> is silent.</li><li><strong><code>/verify</code></strong> before logging off: types, formatting, lint, git, unit tests, and Status against the git log and <code>Done.md</code>.</li></ol><h2 id="design-and-ideas" tabindex="-1">Design and ideas <a class="header-anchor" href="#design-and-ideas" aria-label="Permalink to &quot;Design and ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You say...</th><th>What happens</th></tr></thead><tbody><tr><td>a change to a mechanic that has a <code>Design/</code> note</td><td>Claude edits that note and its index row (the <code>design-talk</code> skill)</td></tr><tr><td>a new idea (<code>/idea &lt;text&gt;</code>, or just saying it)</td><td>it is filed in <code>Brainstorm/</code>, then Claude grills you on it with clickable questions; when it is decent it is promoted to a <code>Design/</code> note, linked both ways</td></tr><tr><td>&quot;what if&quot;, comparisons</td><td>answered in chat, saved only if you ask</td></tr></tbody></table><p><strong><code>/next-design</code></strong> and <strong><code>/next-brainstorm</code></strong> report where the design and the idea pipeline stand.</p><h2 id="skills-and-hooks-keel-ships" tabindex="-1">Skills and hooks Keel ships <a class="header-anchor" href="#skills-and-hooks-keel-ships" aria-label="Permalink to &quot;Skills and hooks Keel ships&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Kind</th><th>Does</th></tr></thead><tbody><tr><td><code>vault-notes</code></td><td>skill (Claude loads it)</td><td>where notes go, keeping them current, the step close</td></tr><tr><td><code>design-talk</code></td><td>skill (Claude loads it)</td><td>routes design talk to <code>Design/</code>, <code>Brainstorm/</code> or chat</td></tr><tr><td><code>/next-system</code>, <code>/next-design</code>, <code>/next-brainstorm</code></td><td>skills (you type them)</td><td>where the build, design or ideas stand, and what&#39;s next</td></tr><tr><td><code>/idea</code></td><td>skill (you type it)</td><td>file an idea and grill it</td></tr><tr><td><code>/verify</code></td><td>skill (you type it)</td><td>whole-project health check</td></tr><tr><td><code>luau-layout</code></td><td>skill (Claude loads it)</td><td>blank-line layout for Luau</td></tr><tr><td><code>note-lookup</code>, <code>docs-check</code></td><td>hooks</td><td>find the notes for a file; flag notes left behind</td></tr><tr><td><code>tag-check</code></td><td>hook</td><td>refuses a <code>git tag</code> without a description</td></tr><tr><td><code>keel-guard</code>, <code>luau-check</code></td><td>hooks</td><td>protect Keel&#39;s files; format, lint and type-check each edit</td></tr></tbody></table><p>All are owned by Keel and replaced on <code>update</code>. A game adds its own in <code>.claude/</code> and documents them in <code>Systems/Game Tooling.md</code>. Details: <a href="/Keel-Docs/guides/tooling">Tooling and hooks</a>.</p>',16)])])}const p=t(a,[["render",n]]);export{g as __pageData,p as default};
